const body = $json.body ?? $json;

const cliente = (body.cliente || "").trim();
const periodo = (body.periodo || "hoy").trim().toLowerCase();

const sin_asignar =
  body.sin_asignar === true ||
  body.sin_asignar === "true" ||
  body.sin_asignar === 1 ||
  body.sin_asignar === "1";

// Fechas para la API de T2000, en hora de Madrid. "semana" = de lunes a domingo; cualquier otro periodo = hoy.
const hoy = $now.setZone('Europe/Madrid').startOf('day');
const desde = periodo === 'semana' ? hoy.startOf('week') : hoy;
const hasta = periodo === 'semana' ? desde.plus({ days: 6 }) : hoy;

return [{
  json: {
    cliente,
    periodo,
    sin_asignar,
    fecha_inicio: desde.toFormat('yyyy-MM-dd'),
    fecha_final: hasta.toFormat('yyyy-MM-dd')
  }
}];

const params = $('Preparar Parametros').first().json;
const r = $input.first()?.json;

// Si falla la llamada, el nodo HTTP sigue por la salida normal con "error"
if (!r || r.error || !Array.isArray(r.pedidos)) {
  const e = r?.error;
  const detalle = e
    ? (typeof e === 'string' ? e : [e.message, e.description].filter(Boolean).join(' — '))
    : 'respuesta inesperada';
  return [{ json: { text: `No he podido consultar los pedidos en T2000 (${String(detalle).slice(0, 200)}).` } }];
}

const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const unicos = a => [...new Set(a.map(x => String(x ?? '').trim()).filter(Boolean))];
const lista = v => Array.isArray(v) ? v : Object.values(v ?? {});

// Origen y destino vienen como código: la población está en origen_destinos
const lugares = new Map(lista(r.origen_destinos).map(o => [String(o.Codigo), o]));
const lugar = cod => lugares.get(String(cod))?.Poblacion || cod || '';

// El conductor está en los movimientos del pedido
const conductor = p => unicos((p.movimientos ?? []).flatMap(m => [m.NombreConductor, m.NombreConductor2])).join(', ');

const buscado = norm(params.cliente);
const filtrados = r.pedidos
  .filter(p => !buscado || norm(p.NombreCliente).includes(buscado))
  .filter(p => !params.sin_asignar || !String(p.MatriculaVehiculo ?? '').trim())
  .sort((a, b) => String(b.FechaCarga ?? '').localeCompare(String(a.FechaCarga ?? '')));

if (filtrados.length === 0) {
  return [{ json: { text: "No he encontrado pedidos con esos filtros." } }];
}

const LIMITE = 50;
const rows = filtrados.slice(0, LIMITE);

let texto = `He encontrado ${filtrados.length} pedido(s)` +
  (filtrados.length > LIMITE ? ` (muestro los ${LIMITE} más recientes)` : '') + `:\n\n`;

for (const p of rows) {
  texto += `📦 Pedido ${p.NumeroPedido}\n`;
  texto += `Cliente: ${p.NombreCliente}\n`;
  texto += `Fecha carga: ${p.FechaCarga}\n`;
  texto += `Ruta: ${lugar(p.Origen)} → ${lugar(p.Destino)}\n`;
  texto += `Matrícula: ${p.MatriculaVehiculo || "sin asignar"}\n`;
  texto += `Conductor: ${conductor(p) || "sin asignar"}\n`;

  if (p.Importe !== null && p.Importe !== undefined) {
    const importe = Number(p.Importe);
    texto += `Importe: ${Number.isFinite(importe) ? importe.toFixed(2) : p.Importe} €\n`;
  }

  texto += `\n`;
}

return [{ json: { text: texto } }];

